targets.rawSql:
select date_trunc('year', "Inbetriebnahmedatum"::timestamp) as time, avg("Bruttoleistung")/1000 as "Nennleistung Ø", avg("Nabenhoehe") as "Nabenhöhe Ø", avg("Rotordurchmesser") as "Rotordurchmesser Ø"
from mastr.wind_extended where "WindAnLandOderAufSee" = 'Windenergie an Land' and "EinheitBetriebsstatus" <> 'In Planung' and "Inbetriebnahmedatum" >= '1995-01-01' and $__timeFilter("Inbetriebnahmedatum") and ('$bundesland'='Alle' or "Bundesland"='$bundesland')
group by 1 order by 1
